<script setup>
import { computed, onMounted, ref } from 'vue'
import { getGrowthResults } from '@/api/growth'
import { useOrganizationStore } from '@/stores/organization'
const organization = useOrganizationStore(), data = ref(null), loading = ref(true), error = ref('')
const stats = computed(() => ({ projects: data.value?.acquisition?.projects?.length || 0, plans: data.value?.acquisition?.plans?.length || 0, analyses: data.value?.sales?.analyses?.length || 0, tasks: data.value?.sales?.trainingTasks?.filter(item => item.status === 'completed').length || 0 }))
onMounted(async () => { try { await organization.load(); data.value = await getGrowthResults({ headers: organization.headers() }) } catch (e) { error.value = e.message } finally { loading.value = false } })
</script>
<template><main class="page"><header><span class="eyebrow">MY RESULTS</span><h1>我的成果</h1><p>系统自动沉淀诊断、行动计划、销售复盘和训练成果。</p></header><section class="stats"><div><small>获客项目</small><strong>{{ stats.projects }}</strong></div><div><small>行动方案</small><strong>{{ stats.plans }}</strong></div><div><small>销售报告</small><strong>{{ stats.analyses }}</strong></div><div><small>已完成训练</small><strong>{{ stats.tasks }}</strong></div></section><p v-if="loading" class="state">正在汇总机构成果…</p><p v-else-if="error" class="state error">{{ error }}</p><section v-else class="grid"><article class="panel"><h2>最近获客成果</h2><div v-if="!data?.acquisition?.projects?.length" class="empty">暂无项目</div><div v-for="item in data.acquisition.projects.slice(0,6)" :key="item.id" class="row"><div><b>{{ item.name }}</b><small>{{ item.goal || '持续获客增长' }}</small></div><span>{{ item.status==='active'?'执行中':'已归档' }}</span></div><router-link to="/growth/acquisition">进入获客引擎</router-link></article><article class="panel"><h2>最近销售复盘</h2><div v-if="!data?.sales?.analyses?.length" class="empty">暂无报告</div><div v-for="item in data.sales.analyses.slice(0,6)" :key="item.id" class="row"><div><b>{{ item.scene==='renewal'?'续费复盘':'新签复盘' }}</b><small>{{ item.level || item.status }}</small></div><strong>{{ item.score ?? '—' }}分</strong></div><router-link to="/growth/sales-coach">进入销售教练</router-link></article><article class="panel wide"><h2>陪跑服务</h2><div class="service"><span>进行中的服务项目 {{ data?.service?.programs?.filter(i=>i.status==='active').length || 0 }}</span><span>开放异常 {{ data?.service?.alerts?.filter(i=>i.status==='open').length || 0 }}</span><span>待执行触点 {{ data?.service?.touchpoints?.filter(i=>i.status==='pending').length || 0 }}</span></div><router-link to="/growth/services">查看服务中心</router-link></article></section></main></template>
<style scoped>.page{min-height:100vh;padding:42px clamp(20px,5vw,64px);background:#f5f3ec;color:#17231c}header,.stats,.grid,.state{max-width:1280px;margin:0 auto}h1{font-size:32px;margin:10px 0 8px}.eyebrow{color:#8b681e;font-size:11px;font-weight:800;letter-spacing:1px}header p,.empty,.state{color:#6b756f}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:28px}.stats div,.panel{background:#fff;border:1px solid #dce2dc;border-radius:14px;padding:18px}.stats small,.row small{color:#778079}.stats strong{display:block;font-size:25px;margin-top:8px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:18px}.panel h2{font-size:17px;margin-bottom:10px}.row{display:flex;justify-content:space-between;align-items:center;padding:12px 0;border-bottom:1px solid #edf0ed}.row small{display:block;margin-top:4px}.row span{font-size:11px;color:#8b681e}.panel>a{display:inline-block;margin-top:16px;color:#1e563a;font-weight:700}.wide{grid-column:1/-1}.service{display:flex;gap:12px;flex-wrap:wrap}.service span{background:#f5f3ec;border-radius:8px;padding:10px 14px}.state{padding:28px 0}.error{color:#a33}@media(max-width:800px){.stats,.grid{grid-template-columns:repeat(2,1fr)}.grid{display:block}.panel{margin-top:12px}}</style>
